// Run with node --experimental-strip-types scripts/seed-community.mjs.
// Reproducible original editorial registry; no Auth identities or fake threads.
import { writeFileSync } from "node:fs";
import {
  communityCategories,
  communityTags,
  editorials,
} from "../src/community/content.ts";
const q = (value) => "'" + String(value).replaceAll("'", "''") + "'";
if (
  editorials.length !== 48 ||
  new Set(editorials.map((x) => x.slug)).size !== 48
)
  throw new Error("Expected 48 distinct editorial resources");
const sql =
  "-- Generated by scripts/seed-community.mjs from original editorial content.\n" +
  "insert into public.community_editorials(slug,category,title,kind) values\n" +
  editorials
    .map(
      (x) => "(" + [x.slug, x.category, x.title, x.kind].map(q).join(",") + ")",
    )
    .join(",\n") +
  "\non conflict(slug) do update set category=excluded.category,title=excluded.title,kind=excluded.kind;\n" +
  "insert into public.community_tags(id,label,family) values\n" +
  communityTags
    .map((x) => "(" + [x.id, x.label, x.family].map(q).join(",") + ")")
    .join(",\n") +
  "\non conflict(id) do update set label=excluded.label,family=excluded.family;\n" +
  "insert into public.community_tags(id,label,family,member_assignable) values('status:reviewed','Technically reviewed','Technical status',false) on conflict(id) do nothing;\n";
writeFileSync(
  new URL("../database/community-editorials.sql", import.meta.url),
  sql,
);
process.stdout.write(
  JSON.stringify({
    editorials: editorials.length,
    categories: communityCategories.length,
    tags: communityTags.length,
  }) + "\n",
);
